    import json
    rows=[];raw_total=0
    for b in BEATS:
        bid,text,kind,ref,motion,trans=b
        w=len(text.split());raw=w/WPS;raw_total+=raw
        rows.append(dict(id=bid,text=text,kind=kind,ref=ref,motion=motion,transition=trans,words=w,_raw=raw))
    target=REAL_WORDS/WPS;scale=target/raw_total;total=0
    for r in rows:
        r["durationSec"]=round(max(3.6,r.pop("_raw")*scale),2);total+=r["durationSec"]
